const connectWithStudioBootstrap = async (pool: Pool): Promise<PoolClient & QueryClient> => {
  try {
    return (await pool.connect()) as PoolClient & QueryClient;
  } catch (error) {
    const bootstrapped = await bootstrapStudioAppDbUserIfNeeded(error);
    if (!bootstrapped) {
      throw error;
    }
    return (await pool.connect()) as PoolClient & QueryClient;
  }
};

